<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';import {write} from './client';import {useSession} from './session';import {useTask} from './ui';import Status from './Status.vue';
const task=useTask(),session=useSession(),password=ref(''),confirmation=ref('');onBeforeUnmount(()=>password.value='');
async function download(){await task.run(async()=>{const data=await write<unknown>('/services/user/account-privacy/export','POST',{password:password.value});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='account-data.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';task.message.value='账户资料已下载；此文件包含个人信息，请妥善保存。';});}
async function deactivate(){await task.run(async()=>{const receipt=await write('/services/user/account-privacy/deletion','POST',{password:password.value,confirmation:confirmation.value});const url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='account-deactivation-receipt.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';confirmation.value='';await session.logout();});}
</script>
<template><section class="section"><h3>账户资料与注销</h3><p>下载包含账户资料和同意记录，并登记完整跨业务导出申请供运营审核。注销将禁用账户并清除公开资料；订单、学习和安全历史按保留规则处理，不会立即永久删除。</p><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><el-input v-model="password" type="password" autocomplete="current-password" aria-label="账户操作验证密码" placeholder="输入当前密码验证"/><el-button :disabled="!password||task.busy.value" @click="download">下载账户资料并申请完整导出</el-button><template v-if="session.role===2"><el-input v-model="confirmation" aria-label="注销确认文字" placeholder="输入“注销账户”确认"/><el-popconfirm title="注销后不能登录，交易与学习历史按保留规则处理，确认继续？" @confirm="deactivate"><template #reference><el-button type="danger" :disabled="!password||confirmation!=='注销账户'||task.busy.value">注销账户</el-button></template></el-popconfirm></template></section></template>
